#include <cstdio>
using namespace std;

const int N = 105;

int n, m;
char s[N][N];
int x1, x2, y1, y2;

int main() {
    scanf("%d%d", &n, &m);
    scanf("%d%d%d%d", &x1, &x2, &y1, &y2);
    for (int i = 1; i <= n; i++)
        scanf("%s", s[i] + 1);
    for (int i = x1; i <= x2; i++) {
        s[i][y2 + 1] = 0;
        printf("%s\n", s[i] + y1);
    }
    return 0;
}

#include <cstdio>
#include <algorithm>
#include <vector>
#include <iostream>
using namespace std;

int main() {

    int n, ans = 0;
    scanf("%d", &n);
    vector<pair<int,int>> a(n);

    for (int i = 0; i < n; i ++)
        scanf("%d%d", &a[i].first, &a[i].second);

    for (int i = 0; i < n; i ++)
        for (int j = i + 1; j < n; j ++)
            if (a[i] < a[j])
                ans ++;

    cout << ans << '\n';
    return 0;
}
